"""Offline, plain-language operating guides. No external links are required."""
from html import escape

PAGE_GUIDES = {
    'Project': ('Start a calibration job', ['Enter the board revision, channel and tag so you can identify this test later.', 'Use Load Demo Project to explore synthetic data. Use New Project before importing real measurements.', 'Save your project before switching projects. Load Project lets you continue a saved job.'], 'A project stores your measurements, assigned angles/distances and analysis settings. Keep separate projects for different channels or board configurations.'),
    'Import Data': ('Tell the app what you measured', ['Choose angle for a stationary tag, distance for range tests, or movement for a moving tag.', 'Enter the known physical angle/distance and choose EVB-CUSTOM for your PCB or EVB-EVB for the reference board.', 'For an angle sweep, open Angle Capture Checklist, select the physical angle, then import that angle’s file. Each capture saves immediately.', 'For range tests, supply measured metres in the log/CSV or attach an ordered distance list.', 'Run Analysis after changes, or use Prepare Final Results in the checklist to save a complete result bundle.'], 'The checklist supports −180° to +180°. The AoA lookup uses a selected sector because two antennas may not uniquely identify front and back. Header range codes are not physical distances unless you explicitly configure their scale.'),
    'Raw Data': ('Check the readings before trusting a result', ['Type in the filter box to find a dataset or value. Click a column heading to sort.', 'Compare pdoa_deg (original phase), pdoa_unwrapped (phase with wrap jumps removed) and pdoa_corrected (phase after the zero-angle offset).', 'valid = False marks a rejected or missing calibration reading. rejection_reason explains why.', 'tdoa_raw is the firmware’s stored value; tdoa_signed decodes its positive/negative meaning.'], 'Original values are preserved. Power columns contain raw diagnostic numbers, not dBm. Missing values mean unavailable data, not zero.'),
    'Fixed Angle Analysis': ('Turn stationary captures into an angle lookup', ['Import captures at known angles, including 0°, with the tag stationary at a consistent distance.', 'Start with MAD filtering and linear interpolation. The settings description explains these choices.', 'Click Run Analysis / Refresh All Pages. Choose a chart in Plots; use Statistics / details for the numbers.', 'Inspect phase spread and the angle trend before checking Calibration Results. A usable trend should keep the same direction as physical angle increases.'], 'PDoA is the measured phase difference between receive paths. AoA is the physical arrival angle. The zero offset is the phase measured at physical 0°. Subtracting it makes that point the reference. A lookup table (LUT) then maps measured phase to angle.'),
    'Distance / Antenna Delay': ('Find a consistent distance offset', ['Import distance datasets at several known distances, such as 1, 2, 3 and 5 metres.', 'Provide actual measured distances, then run analysis from Fixed Angle Analysis.', 'Compare Measured distance and Range error plots. Read the bias and regression in Statistics / details.', 'Give the external physical correction to the firmware team; they must confirm the firmware conversion.'], 'Range error = measured distance − true distance. Positive error means the device reads too far. A constant bias is consistent with a fixed offset; changing bias with distance needs investigation. Equivalent delay is a physical quantity, not a guessed register value. Never overwrite factory OTP calibration.'),
    'Movement Analysis': ('Find when the readings become unstable', ['Import a continuous moving-tag file as movement, then run analysis.', 'Compare phase, time difference, range, power and first-path charts at the same time.', 'Check the events and conclusion under Statistics / details. A jump in one field is evidence to inspect, not proof of a hardware fault.'], 'The horizontal axis uses elapsed seconds where timestamps exist, otherwise sample order. Raw phase can jump from +180° to −180° even during smooth motion. Unwrapped phase removes that boundary jump, assuming measurements are close enough together.'),
    'EVB vs Custom Comparison': ('Compare boards at the same operating point', ['Import both EVB-EVB and EVB-CUSTOM captures at matching physical angles and distances.', 'Run analysis. The table below matches datasets by test type, angle and distance.', 'Compare each board’s mean and spread. A higher power number or timing value is not automatically better.'], 'Mean is the average reading. Standard deviation (SD) describes spread: a smaller spread usually means more repeatable readings at a fixed position. Absolute difference shows the size of the gap between the two means. Power ratios use raw diagnostic values.'),
    'Calibration Results': ('Decide what can be handed to firmware', ['Check the readiness summary first, then inspect warnings and validation errors.', 'PASS means a project criterion was met. WARNING means review or more data is needed. FAIL blocks the affected calibration.', 'READY means the LUT meets the configured project criteria. It is not a Murata certification or proof of correct RF hardware.', 'If readings are unstable or the phase trend reverses strongly, investigate captures and RF conditions before using a lookup.'], 'Validation leaves out one known angle and predicts it from the others. MAE is the average size of these errors; maximum error is the worst one. The defaults are project-specific, not manufacturer specifications. Reversed orientation recommends a sign/order check, not an automatic firmware change.'),
    'Export': ('Save results for review and firmware integration', ['Use Full measurements CSV to inspect all enabled readings and rejection flags in a spreadsheet.', 'Use Calibration LUT CSV or Firmware C header for a candidate lookup. Read the readiness flag and sign/offset convention first.', 'Use Calibration JSON for structured results, or Engineering HTML report for the plots and explanations.', 'For the complete sweep bundle, use Prepare Final Results in the angle checklist. Save the project too if you want to continue later.'], 'Exports refresh analysis. Physical corrections are in degrees, metres and equivalent delay; firmware units and factory-calibration handling must still be confirmed. Open HTML reports locally in a browser and use Print to PDF if needed.'),
}

PLOT_GUIDES = [
    ('Raw PDoA', 'Each dot is one original phase reading at a known physical angle. A narrow cluster means steadier readings. Red crosses mark rejected/missing-filter samples with available values. Jumps near ±180° may be phase wrapping.', 'Horizontal: known physical angle (°). Vertical: original phase difference (°).'),
    ('Corrected PDoA', 'This removes the 0° phase offset and aligns phase branches. The point at physical 0° should be near zero. A useful lookup trend keeps increasing or keeps decreasing. Backward steps need review.', 'Horizontal: known angle (°). Vertical: phase after zero-offset correction (°).'),
    ('PDoA spread', 'This shows how much phase varies at each fixed angle. Lower points mean steadier measurements. Large spread can make the calculated angle flicker. At least two accepted readings are needed to calculate spread.', 'Horizontal: known angle (°). Vertical: phase standard deviation (°).'),
    ('Mean TDoA', 'This shows the average signed receive-time difference at each angle. A smooth repeatable trend is useful evidence. These are raw timing units; the app does not convert them to physical time.', 'Horizontal: known angle (°). Vertical: average signed TDoA (raw units).'),
    ('TDoA spread', 'Lower values mean the time difference is more repeatable at a stationary position. Large spread or isolated peaks deserve inspection. At least two accepted readings are needed.', 'Horizontal: known angle (°). Vertical: TDoA standard deviation (raw units).'),
    ('STS powers', 'Compare the two receive paths at the same angle. A persistent large gap can indicate imbalance worth investigating. Raw power numbers are not dBm, and a bigger number is not automatically better.', 'Horizontal: known angle (°). Vertical: raw STS1/STS2 power diagnostics.'),
    ('First-path difference', 'This compares where the two paths detect the start of the signal. A repeatable offset may be systematic. Wide scatter or sudden changes can affect angle stability. Index units are not converted to time.', 'Horizontal: known angle (°). Vertical: STS2 first-path index minus STS1 (raw index units).'),
    ('Measured distance', 'The dashed line is the ideal reading: measured distance equals true distance. Dots above it read too far; dots below it read too short. A similar gap at every distance suggests a fixed bias.', 'Horizontal: true distance (m). Vertical: measured distance (m).'),
    ('Range error', 'The dashed zero line means no distance error. Positive dots mean the device reads too far; negative dots mean it reads too short. A flat band away from zero suggests a consistent offset.', 'Horizontal: true distance (m). Vertical: measured minus true distance (m).'),
    ('PDoA over time', 'Raw phase can jump at the ±180° boundary. Compare it with unwrapped phase: if only the raw line jumps, wrapping may explain it. Sudden unwrapped changes need inspection, considering real motion and sample gaps.', 'Horizontal: elapsed seconds, or sample order if timestamps are absent. Vertical: phase (°).'),
    ('TDoA over time', 'Look for sudden spikes in signed timing difference and compare their times with phase/range/power changes. Spikes are diagnostic evidence, not a definite hardware fault.', 'Horizontal: elapsed seconds or sample order. Vertical: signed TDoA (raw units).'),
    ('Range over time', 'Look for sudden measured-distance changes. Compare them with expected tag motion and the other charts. A distance jump can disturb movement visualization even if the angle is steady.', 'Horizontal: elapsed seconds or sample order. Vertical: measured distance (m).'),
    ('STS powers over time', 'Compare both receive-path powers as the tag moves. Persistent separation or sudden dips are worth checking alongside phase jumps. Values are raw diagnostics, not dBm.', 'Horizontal: elapsed seconds or sample order. Vertical: raw STS1/STS2 power.'),
    ('First paths over time', 'These show where each path detects the signal start. Sudden steps may reflect changed signal detection, reflections or movement. Compare their times with other events before drawing conclusions.', 'Horizontal: elapsed seconds or sample order. Vertical: STS1/STS2 first-path indices (raw units).'),
]


def page_guide(name):
    title, steps, meaning = PAGE_GUIDES[name]
    html = '<h2>' + escape(title) + '</h2><h3>What to do</h3><ol>'
    html += ''.join('<li>' + escape(step) + '</li>' for step in steps) + '</ol><h3>What it means</h3><p>' + escape(meaning) + '</p>'
    indices = range(7) if name == 'Fixed Angle Analysis' else range(7, 9) if name == 'Distance / Antenna Delay' else range(9, 14) if name == 'Movement Analysis' else []
    for i in indices:
        title, description, axes = PLOT_GUIDES[i]
        html += '<h3>' + escape(title) + '</h3><p>' + escape(description) + '</p><p><i>' + escape(axes) + '</i></p>'
    return html + '<h3>Plot controls</h3><p>Home resets the view. Pan moves the view. Zoom enlarges an area. Save writes the chart as an image. Use Run Analysis after changing datasets or settings.</p>'
